import { GoldenLayout, LayoutConfig } from "/ui/vendor/golden-layout.esm.js";
import { disposeThreeScene, renderThreeScene } from "/ui/scene3d.js?v=5";

const names={simulator:"Simulation map",scene3d:"3D scene",editor:"Scenario map",editor3d:"3D preview",editorTools:"Editor tools",editorProperties:"Cell properties",editorScenario:"Scenario settings",controls:"Mission controls",inspector:"Inspector",json:"Scenario JSON",events:"Event stream"};
const modeKey="sarsim.workspace.mode.v1";
const layoutKeys={simulation:"sarsim.layout.simulation.v3",editing:"sarsim.layout.editing.v2"};
const panelKinds={simulation:["simulator","scene3d","controls","inspector","events"],editing:["editor","editor3d","editorTools","editorProperties","editorScenario","json"]};
const defaultLayouts={simulation:{settings:{popoutWholeStack:false,reorderEnabled:true},dimensions:{borderWidth:5,borderGrabWidth:10,headerHeight:28},root:{type:"row",content:[{type:"component",componentType:"controls",title:names.controls,size:"20%",minSize:"235px"},{type:"stack",size:"56%",minSize:"430px",activeItemIndex:0,content:[{type:"component",componentType:"simulator",title:names.simulator},{type:"component",componentType:"scene3d",title:names.scene3d}]},{type:"column",size:"24%",minSize:"260px",content:[{type:"component",componentType:"inspector",title:names.inspector,size:"38%"},{type:"component",componentType:"events",title:names.events,size:"62%"}]}]}},editing:{settings:{popoutWholeStack:false,reorderEnabled:true},dimensions:{borderWidth:5,borderGrabWidth:10,headerHeight:28},root:{type:"row",content:[{type:"column",size:"22%",minSize:"245px",content:[{type:"component",componentType:"editorTools",title:names.editorTools,size:"43%"},{type:"component",componentType:"editorScenario",title:names.editorScenario,size:"57%"}]},{type:"stack",size:"55%",minSize:"430px",activeItemIndex:0,content:[{type:"component",componentType:"editor",title:names.editor},{type:"component",componentType:"editor3d",title:names.editor3d}]},{type:"column",size:"23%",minSize:"280px",content:[{type:"component",componentType:"editorProperties",title:names.editorProperties,size:"58%"},{type:"component",componentType:"json",title:names.json,size:"42%"}]}]}}};
const blank=()=>({schema_version:"1.0",metadata:{scenario_id:"browser-scenario",name:"Browser Scenario"},grid:{N:10,Z:3,cells:[],smoke:[]},agents:[],casualties:[],buildings:[],zones:[],scheduled_events:[],objectives:{},evaluation:{expected_difficulty:"medium"},perception:{regime:"FULL",range:4,cone_angle_degrees:90}});
const app={mode:"simulation",runtime:null,z:0,agent:null,casualty:null,cell:null,running:false,timer:null,editor:blank(),editorText:"",editorZ:0,tool:"select",editorCell:null,activeZoneId:null,editorStatus:"Select a labeled tool, then click a cell to begin authoring.",scenarios:[],scenarioPath:"",keyboardBusy:false,keyboardStatus:"WASD moves · C cycles agents · Space acts ahead",keyboardHighlight:[],keyboardHighlightTimer:null};
app.editorText=JSON.stringify(app.editor,null,2);

const layoutHost=document.querySelector("#layout");
const layout=new GoldenLayout(layoutHost);
for(const kind of Object.keys(names))layout.registerComponentFactoryFunction(kind,container=>{const el=document.createElement("section");el.className="panel";el.dataset.panel=kind;container.element.append(el);container.on("destroy",()=>disposeThreeScene(el));renderPanel(el,kind)});
window.addEventListener("resize",resizeLayout);

async function api(path,options={}){const response=await fetch(path,options);if(!response.ok){let detail=await response.text();try{detail=JSON.parse(detail).detail}catch(_){}throw new Error(`${options.method||"GET"} ${path} (${response.status}): ${detail}`)}return response.headers.get("content-type")?.includes("json")?response.json():response.text()}
const post=(path,body)=>api(path,{method:"POST",headers:body===undefined?undefined:{"Content-Type":"application/json"},body:body===undefined?undefined:JSON.stringify(body)});
async function refresh(){app.runtime=await api("/state");const ids=Object.keys(app.runtime.agents);if(!app.agent||!app.runtime.agents[app.agent])app.agent=ids[0]||null;app.z=Math.min(app.z,app.runtime.z_levels-1);if(app.casualty&&!runtimeCoordVisible(app.runtime.casualties[app.casualty]))app.casualty=null;if(app.cell&&!runtimeCoordVisible(app.cell))app.cell=null;if(app.runtime.ended)app.keyboardStatus=app.runtime.success?"Mission complete · reload the scenario to run it again":"Mission ended · reload the scenario before issuing more actions";connection(true);renderAll()}
function connection(ok){document.querySelector("#status-dot").className=ok?"online":"offline";document.querySelector("#status-label").textContent=ok?"Engine online":"Engine unavailable"}
function renderAll(){document.querySelector("#tick").textContent=app.runtime?.tick??"—";document.querySelector("#agent-count").textContent=app.runtime?Object.keys(app.runtime.agents).length:"—";updateWorkspaceChrome();document.querySelectorAll("[data-panel]").forEach(el=>renderPanel(el,el.dataset.panel))}
const heading=(over,text,aside="")=>`<div class="title"><div><span class="eyebrow">${esc(over)}</span><h2>${esc(text)}</h2></div><span class="muted mono">${esc(aside)}</span></div>`;
function renderPanel(el,kind){if(kind==="scene3d"){renderThreeScene(el,app.runtime,{onSelect:selection=>selectThreeObject(selection,false),visibleCells:runtimeVisibility(),sensorRegime:app.runtime?.perception?.regime||"FULL",controlledAgentId:app.agent});return}if(kind==="editor3d"){renderThreeScene(el,app.editor,{onSelect:selection=>selectThreeObject(selection,true)});return}el.innerHTML=({simulator,editor,editorTools,editorProperties,editorScenario,controls,inspector,json:jsonPanel,events})[kind]?.()||""}
function selectThreeObject(selection,editing){const coord=selection.coord?{...selection.coord}:null;if(editing){if(coord)app.editorCell=coord;app.editorStatus=`Selected ${selection.kind}${selection.id?` ${selection.id}`:""} in 3D preview`}else{if(coord)app.cell=coord;if(selection.kind==="agent")app.agent=selection.id;if(selection.kind==="casualty")app.casualty=selection.id}renderAll()}

function simulator(){const s=app.runtime;if(!s)return `<div class="body">${heading("Live environment","Simulation map")}<div class="empty">Waiting for simulation state…</div></div>`;const visible=runtimeVisibility(),sees=value=>!visible||visible.has(coordKey(value)),cells=new Map(s.grid_cells.filter(c=>c.z===app.z).map(c=>[`${c.x},${c.y}`,c]));const buildings=new Map(Object.values(s.buildings).flatMap(b=>b.cells).filter(c=>c.z===app.z).map(c=>[`${c.x},${c.y}`,c]));const agents=new Map(Object.values(s.agents).filter(a=>a.z===app.z).map(a=>[`${a.x},${a.y}`,a]));const casualties=new Map(Object.values(s.casualties).filter(c=>c.z===app.z&&c.transport_status!=="LOADED").map(c=>[`${c.x},${c.y}`,c]));const zones=zoneMap(s.zones,app.z);let html="";for(let y=0;y<s.grid_size;y++)for(let x=0;x<s.grid_size;x++){const key=`${x},${y}`,coord={x,y,z:app.z},isVisible=sees(coord),c=cells.get(key),a=agents.get(key),cas=casualties.get(key),b=buildings.get(key),z=zones.get(key),selected=app.cell?.x===x&&app.cell?.y===y&&app.cell?.z===app.z;html+=cellHtml(x,y,app.z,`${classes(c,b,z,cas,a)} ${isVisible?"":"unseen"}`,selected,a?`<span class="agent ${a.agent_class.toLowerCase()}">${arrow(a.orientation)} ${esc(a.id)}</span>`:cas?`<span class="casualty">✚ ${esc(cas.id)}</span>`:"",cellBadge(c,b,z,cas,a),"runtime-cell",!isVisible)}const regime=s.perception?.regime||"FULL";return `<div class="body map-wrap">${heading("Live environment","Simulation map",`${s.grid_size}×${s.grid_size} / z ${app.z} · ${sensorLabel(regime)}`)}<div class="toolbar"><button data-command="z-down">− Z</button><span class="level">LEVEL ${app.z}</span><button data-command="z-up">+ Z</button><button data-command="refresh">↻ Refresh</button></div>${mapLegend()}<div class="sensor-banner"><b>${sensorLabel(regime)}</b><span>${regime==="FULL"?"Unrestricted operator view":`Controlled-agent visibility · range ${s.perception.range}`}</span></div><div class="grid" style="--n:${s.grid_size}">${html}</div></div>`}
function cellHtml(x,y,z,css,selected,token,badge,data,disabled=false){return `<button class="cell ${css} ${selected?"selected":""}" data-${data}="${x},${y},${z}" ${disabled?"disabled":""}><span class="coord">${x}:${y}</span><span class="token">${token}</span><span class="badge">${badge}</span></button>`}
function classes(cell,building,zones,casualty,agent){const status=cell?.status||"UNOCCUPIED";return [status.toLowerCase(),status==="IMPASSABLE"?"wall":"",status==="PASSABLE"?"debris":"",cell?.smoke_density>0?"smoke":"",building?"building":"",building?.collapsed?"collapsed":"",zones?.length?"zone":"",zones?.some(z=>z.zone_type==="EXTRACTION")?"extraction":"",zones?.some(z=>z.zone_type==="FIELD_HOSPITAL")?"hospital":"",casualty?"casualty-present":"",casualty?.is_covered?"covered":"",casualty&&casualty.triage_state!=="UNKNOWN"?"triaged":"",casualty?.living_state==="DECEASED"?"deceased":"",agent?"agent-present":"",agent?.agent_class==="UAV"?"agent-uav":"",agent?.payload_casualty_id?"carrying":""].join(" ")}
function cellBadge(cell,building,zones,casualty,agent){const labels=[];if(cell?.status&&cell.status!=="UNOCCUPIED")labels.push(cell.status);if((cell?.smoke_density||0)>0)labels.push(`SMK ${cell.smoke_density.toFixed(1)}`);if(building)labels.push(building.collapsed?"COLLAPSED":"BLDG");if(zones?.some(z=>z.zone_type==="FIELD_HOSPITAL"))labels.push("HOSP");else if(zones?.some(z=>z.zone_type==="EXTRACTION"))labels.push("EXT");if(casualty?.is_covered)labels.push("COVERED");if(agent?.payload_casualty_id)labels.push("PAYLOAD");return labels.join(" · ")}
function mapLegend(){return `<div class="map-legend" aria-label="Map legend"><div class="legend-group"><strong>Cell status</strong><span class="legend-item"><i class="legend-cell unoccupied"></i><b>UNOCCUPIED</b><small>open</small></span><span class="legend-item"><i class="legend-cell passable"></i><b>PASSABLE</b><small>debris</small></span><span class="legend-item"><i class="legend-cell impassable"></i><b>IMPASSABLE</b><small>wall</small></span></div><div class="legend-group"><strong>Overlays</strong><span class="legend-item"><i class="legend-cell smoke"></i>Smoke</span><span class="legend-item"><i class="legend-cell building"></i>Building</span><span class="legend-item"><i class="legend-cell collapsed"></i>Collapsed</span><span class="legend-item"><i class="legend-cell extraction"></i>Extraction</span><span class="legend-item"><i class="legend-cell hospital"></i>Field hospital</span></div><div class="legend-group"><strong>Entities</strong><span class="legend-item legend-agent">▲ UGV</span><span class="legend-item legend-uav">◆ UAV</span><span class="legend-item legend-casualty">✚ Casualty</span><span class="legend-item legend-triaged">✚ Triaged</span><span class="legend-item legend-deceased">✚ Deceased</span><span class="legend-item legend-covered">Covered</span><span class="legend-item legend-carrying">Carrying</span></div></div>`}

function controls(){const s=app.runtime,agents=s?Object.values(s.agents):[],casualties=s?Object.values(s.casualties).filter(c=>runtimeCoordVisible(c)||c.id===s.agents?.[app.agent]?.payload_casualty_id):[],scenario=app.scenarios.find(v=>v.path===app.scenarioPath);return `<div class="body">${heading("Execution","Mission controls",s?`cycle ${s.tick}`:"offline")}<div class="toolbar"><button class="primary" data-command="step">Step</button><button class="${app.running?"active":""}" data-command="run">${app.running?"Pause":"Run"}</button><button class="danger" data-command="reset">Reset</button></div><div class="field"><label>Bundled scenario</label><div class="scenario-row"><select data-control="scenario"><option value="">Choose a scenario…</option>${app.scenarios.map(v=>`<option value="${esc(v.path)}" ${v.path===app.scenarioPath?"selected":""}>${esc(v.name)} · ${esc(sensorLabel(v.sensor_regime||"FULL"))}</option>`).join("")}</select><button data-command="load-scenario" ${app.scenarioPath?"":"disabled"}>Load</button></div><div class="scenario-description">${scenario?`Sensor: ${esc(sensorLabel(scenario.sensor_regime||"FULL"))} · ${esc(scenario.description||"No description")}`:esc(`${app.scenarios.length} authored scenarios available`)}</div></div><div class="stats"><div class="stat"><small>Agents</small><b>${agents.length}</b></div><div class="stat"><small>Visible casualties</small><b>${casualties.length}</b></div><div class="stat"><small>Rescued</small><b>${s?.temporal_constraint?.rescued_count??0}</b></div></div><div class="field"><label>Controlled agent</label><select data-control="agent">${agents.map(a=>`<option value="${esc(a.id)}" ${a.id===app.agent?"selected":""}>${esc(a.id)} · ${a.agent_class} · (${a.x},${a.y},${a.z})</option>`).join("")}</select></div><div class="field"><label>Target casualty</label><select data-control="casualty"><option value="">None</option>${casualties.map(c=>`<option value="${esc(c.id)}" ${c.id===app.casualty?"selected":""}>${esc(c.id)} · ${Math.round(c.health)} HP</option>`).join("")}</select></div><div class="keyboard-help"><kbd>W</kbd><kbd>A</kbd><kbd>S</kbd><kbd>D</kbd> cardinal movement &nbsp; <kbd>C</kbd> next agent &nbsp; <kbd>SPACE</kbd> contextual action</div><div class="keyboard-status">${esc(app.keyboardStatus)}</div><span class="eyebrow">Navigation</span><div class="actions">${actionButtons([["TURN_LEFT","↶ Left"],["MOVE_FORWARD","↑ Forward"],["TURN_RIGHT","Right ↷"],["ASCEND","Ascend"],["DESCEND","Descend"],["UNLOAD_CASUALTY","Unload"]])}</div><span class="eyebrow">Response</span><div class="actions">${actionButtons([["TRIAGE","Triage"],["LOAD_CASUALTY","Load"],["TRANSFER_CASUALTY","Transfer"],["CLEAR_DEBRIS","Clear"],["BREACH_ENTRYWAY","Breach"],["RETRIEVE_BODY","Retrieve"]])}</div><div class="callout">Coordinate actions target the selected map cell. Casualty actions use the selected casualty.</div></div>`}
const actionButtons=items=>items.map(([value,label])=>`<button data-action="${value}" class="${[value==="MOVE_FORWARD"?"primary":"",app.keyboardHighlight.includes(value)?"keyboard-highlight":""].join(" ")}" ${app.runtime?.ended?"disabled":""}>${label}</button>`).join("");

function editor(){const s=app.editor,z=app.editorZ,cells=new Map(s.grid.cells.filter(c=>c.coord.z===z).map(c=>[`${c.coord.x},${c.coord.y}`,{status:c.status,smoke_density:0}]));for(const smoke of s.grid.smoke)if(smoke.coord.z===z){const key=`${smoke.coord.x},${smoke.coord.y}`;if(!cells.has(key))cells.set(key,{status:"UNOCCUPIED",smoke_density:0});cells.get(key).smoke_density=smoke.density}const agents=new Map(s.agents.filter(a=>a.coord.z===z).map(a=>[`${a.coord.x},${a.coord.y}`,a])),casualties=new Map(s.casualties.filter(c=>c.coord.z===z).map(c=>[`${c.coord.x},${c.coord.y}`,c])),buildings=new Map(s.buildings.flatMap(b=>b.cells).filter(c=>c.coord.z===z).map(c=>[`${c.coord.x},${c.coord.y}`,c])),zones=zoneMap(s.zones,z);let html="";for(let y=0;y<s.grid.N;y++)for(let x=0;x<s.grid.N;x++){const key=`${x},${y}`,a=agents.get(key),cas=casualties.get(key),b=buildings.get(key),zs=zones.get(key),c=cells.get(key);html+=cellHtml(x,y,z,classes(c,b,zs,cas,a),same(app.editorCell,{x,y,z}),a?`<span class="agent ${a.agent_class.toLowerCase()}">${arrow(a.orientation)} ${esc(a.id)}</span>`:cas?`<span class="casualty">✚ ${esc(cas.id)}</span>`:"",cellBadge(c,b,zs,cas,a),"editor-cell")}return `<div class="body map-wrap editor-map-body">${heading("Authoring","Scenario map",`${s.grid.N}×${s.grid.N} / z ${z}`)}<div class="toolbar editor-level"><button data-command="editor-z-down">− Z level</button><span class="level">LEVEL ${z}</span><button data-command="editor-z-up">+ Z level</button><span class="active-tool">Tool: <b>${esc(app.tool)}</b></span></div><div class="editor-status">${esc(app.editorStatus)}</div>${mapLegend()}<div class="editor-map-canvas"><div class="grid" style="--n:${s.grid.N}">${html}</div></div></div>`}
function editorTools(){const tools=[["select","⌖","Select","Inspect and edit a cell"],["wall","▦","Wall","Place impassable terrain"],["debris","▧","Debris","Place passable debris"],["smoke","≋","Smoke","Place a smoke hazard"],["casualty","✚","Casualty","Place at ground level"],["agent","△","Agent","UGV on ground, UAV aloft"],["building","◇","Building","Stack building cells on any level"],["zone","Z","Zone","Toggle active-zone cells"],["clear","×","Clear cell","Remove authored contents"]];return `<div class="body editor-tools-panel">${heading("Authoring","Placement tools",`active: ${app.tool}`)}<p class="panel-intro">Choose a labeled tool, then click the scenario map. Select opens all editable properties for a cell.</p><div class="editor-tools" aria-label="Editor placement tools">${tools.map(([value,mark,label,help])=>`<button class="tool ${app.tool===value?"active":""}" data-tool="${value}" title="${help}"><span class="tool-mark">${mark}</span><span><b>${label}</b><small>${help}</small></span></button>`).join("")}</div><section class="editor-workflow"><h3>Scenario file</h3><div class="command-grid"><button data-editor-action="new-scenario">New blank</button><button data-editor-action="regenerate">Regenerate</button><button data-editor-action="validate">Validate</button><button data-editor-action="download">Save JSON</button><label class="file-button">Open JSON<input hidden type="file" accept=".json,application/json" data-file></label><button class="primary" data-command="apply">Run scenario</button></div></section></div>`}

function editorSelection(){if(!app.editorCell)return null;const {x,y,z}=app.editorCell,ground={x,y,z:0},s=app.editor;const cell=s.grid.cells.find(v=>same(v.coord,{x,y,z})),smoke=s.grid.smoke.find(v=>same(v.coord,{x,y,z})),agent=s.agents.find(v=>same(v.coord,{x,y,z})),casualty=s.casualties.find(v=>same(v.coord,ground)),building=s.buildings.find(v=>v.cells.some(c=>same(c.coord,{x,y,z}))),buildingCell=building?.cells.find(c=>same(c.coord,{x,y,z})),zones=s.zones.filter(v=>v.cells.some(c=>same(c,ground)));return {x,y,z,coord:{x,y,z},ground,cell,smoke,agent,casualty,building,buildingCell,zones}}
function editorProperties(){const selection=editorSelection();return `<div class="body editor-properties editor-properties-panel">${heading("Selection","Cell properties",selection?`${selection.x}, ${selection.y}, ${selection.z}`:"none")}${selection?selectedCellProperties(selection):`<section class="selection-empty"><h3>Nothing selected</h3><p>Choose <b>Select</b> in Editor tools, then click a map cell. Entity, terrain, smoke, and building controls will appear here.</p></section>`}</div>`}
function editorScenario(){const s=app.editor,constraint=s.objectives.temporal_constraint,active=activeZone(),events=s.scheduled_events,lastEvent=events.at(-1);return `<div class="body editor-properties editor-scenario-panel">${heading("Definition","Scenario settings",`${s.casualties.length} casualties`)}<section><h3>Scenario</h3><label>Scenario name<input data-editor-field="scenario-name" value="${esc(s.metadata.name||"")}"></label><label>Scenario ID<input data-editor-field="scenario-id" value="${esc(s.metadata.scenario_id||"")}"></label><label>Difficulty<select data-editor-field="difficulty">${["easy","medium","hard"].map(v=>`<option ${s.evaluation.expected_difficulty===v?"selected":""}>${v}</option>`).join("")}</select></label></section><section><h3>Sensor regime</h3><label>Regime<select data-editor-field="sensor-regime">${[["FULL","Full observability"],["FOV_CONE","FOV cone"],["MINIGRID_3","MiniGrid 3-wide"]].map(([value,label])=>`<option value="${value}" ${s.perception.regime===value?"selected":""}>${label}</option>`).join("")}</select></label><div class="property-pair"><label>Range<input type="number" min="1" max="50" data-editor-field="sensor-range" value="${s.perception.range}" ${s.perception.regime==="FULL"?"disabled":""}></label><label>Cone angle<input type="number" min="1" max="360" step="1" data-editor-field="sensor-angle" value="${s.perception.cone_angle_degrees}" ${s.perception.regime!=="FOV_CONE"?"disabled":""}></label></div><p>${s.perception.regime==="MINIGRID_3"?"Three cells wide with the agent centered on the back row.":s.perception.regime==="FOV_CONE"?"Forward cone blocked by smoke, walls, and buildings.":"All cells and entities are observable."}</p></section><section><h3>Active zone</h3><label>Zone<select data-editor-field="active-zone"><option value="">No active zone</option>${s.zones.map(v=>`<option value="${esc(v.id)}" ${v.id===app.activeZoneId?"selected":""}>${esc(v.id)}</option>`).join("")}</select></label><label>Type<select data-editor-field="zone-type" ${active?"":"disabled"}><option ${active?.zone_type==="EXTRACTION"?"selected":""}>EXTRACTION</option><option ${active?.zone_type==="FIELD_HOSPITAL"?"selected":""}>FIELD_HOSPITAL</option></select></label><div class="property-actions"><button data-editor-action="new-zone">New zone</button><span>${active?`${active.cells.length} cells`:"Create a zone, select Zone, then click map cells."}</span></div></section><section><h3>Mission objective</h3><label class="check"><input type="checkbox" data-editor-field="constraint-enabled" ${constraint?"checked":""}> Rescue-count constraint</label><div class="property-pair"><label>Target<input type="number" min="1" max="${Math.max(1,s.casualties.length)}" data-editor-field="constraint-target" value="${constraint?.target_count||1}" ${constraint?"":"disabled"}></label><label>Deadline<input type="number" min="1" data-editor-field="constraint-deadline" value="${constraint?.deadline_cycles||20}" ${constraint?"":"disabled"}></label></div></section><section><h3>Scheduled events</h3><p>${events.length} events${lastEvent?` · last: ${esc(lastEvent.event_id)} at T+${esc(lastEvent.tick)}`:""}</p><div class="property-actions"><button data-editor-action="add-event" ${app.editorCell?"":"disabled"}>Add smoke at selected cell</button><button data-editor-action="remove-event" ${events.length?"":"disabled"}>Remove last</button></div></section></div>`}

function selectedCellProperties(v){return `<section class="selected-properties"><h3>Selected cell <span>${v.x}, ${v.y}, ${v.z}</span></h3><label>Cell status<select data-editor-field="cell-status">${["UNOCCUPIED","PASSABLE","IMPASSABLE"].map(status=>`<option ${status===(v.cell?.status||"UNOCCUPIED")?"selected":""}>${status}</option>`).join("")}</select></label><label>Smoke density<input type="number" min="0" max="1" step="0.1" data-editor-field="smoke-density" value="${v.smoke?.density||0}"></label>${v.agent?`<div class="property-card agent-card"><h4>Agent ${esc(v.agent.id)}</h4><label>Class<select data-editor-field="agent-class"><option ${v.agent.agent_class==="UGV"?"selected":""}>UGV</option><option ${v.agent.agent_class==="UAV"?"selected":""}>UAV</option></select></label><label>Orientation<select data-editor-field="agent-orientation">${["NORTH","EAST","SOUTH","WEST"].map(o=>`<option ${v.agent.orientation===o?"selected":""}>${o}</option>`).join("")}</select></label><button data-editor-action="remove-agent">Remove agent</button></div>`:""}${v.casualty?`<div class="property-card casualty-card"><h4>Casualty ${esc(v.casualty.id)}</h4><label>Health</label><div class="stepper"><button data-editor-action="health-down">−10</button><input type="number" min="0" max="100" step="1" data-editor-field="casualty-health" value="${v.casualty.health}"><button data-editor-action="health-up">+10</button></div><label>Decay per cycle</label><div class="stepper"><button data-editor-action="decay-down">−0.5</button><input type="number" min="0" step="0.5" data-editor-field="casualty-decay" value="${v.casualty.decay_rate}"><button data-editor-action="decay-up">+0.5</button></div><label class="check"><input type="checkbox" data-editor-field="casualty-covered" ${v.casualty.is_covered?"checked":""}> Covered by debris</label><dl><dt>Triage</dt><dd>${esc(v.casualty.triage_state)}</dd><dt>Living</dt><dd>${esc(v.casualty.living_state)}</dd><dt>Transport</dt><dd>${esc(v.casualty.transport_status)}</dd></dl><button data-editor-action="remove-casualty">Remove casualty</button></div>`:""}${v.buildingCell?`<div class="property-card building-card"><h4>Building ${esc(v.building.id)}</h4><label>Integrity</label><div class="stepper"><button data-editor-action="integrity-down">−0.1</button><input type="number" min="0" max="1" step="0.1" data-editor-field="building-integrity" value="${v.buildingCell.integrity}"><button data-editor-action="integrity-up">+0.1</button></div><label class="check"><input type="checkbox" data-editor-field="building-collapsed" ${v.buildingCell.collapsed?"checked":""}> Collapsed</label><button data-editor-action="remove-building">Remove building</button></div>`:""}${v.zones.length?`<div class="property-card"><h4>Zones at cell</h4><p>${v.zones.map(z=>`${esc(z.id)} · ${esc(z.zone_type)}`).join("<br>")}</p></div>`:""}<button class="danger wide" data-editor-action="clear-selected">Clear selected cell</button></section>`}

function inspector(){const a=app.runtime?.agents?.[app.agent],c=app.runtime?.casualties?.[app.casualty];return `<div class="body">${heading("Selection","Inspector")}${a?card(`Agent ${a.id}`,a):`<div class="empty">Select an agent or map cell to inspect it.</div>`}${c?card(`Casualty ${c.id}`,c):""}${app.cell?card("Runtime cell",app.cell):""}${app.editorCell?card("Editor cell",app.editorCell):""}</div>`}
function card(name,value){return `<article class="card"><h3>${esc(name)}</h3><dl class="kv">${Object.entries(value).filter(([,v])=>typeof v!=="object"||v===null).slice(0,14).map(([k,v])=>`<dt>${esc(k)}</dt><dd class="mono">${esc(v??"—")}</dd>`).join("")}</dl></article>`}
function jsonPanel(){return `<div class="body" style="height:100%">${heading("Source","Scenario JSON","schema 1.0")}<div class="toolbar"><button data-command="new">New</button><button data-command="import">Import runtime</button><button data-command="format">Format</button><button data-command="validate">Validate</button><button class="primary" data-command="apply">Run scenario</button><button data-command="download">Download</button><label><button type="button">Open file</button><input hidden type="file" accept=".json,application/json" data-file></label></div><textarea class="json" data-json spellcheck="false">${esc(app.editorText)}</textarea></div>`}
function events(){const list=[...(app.runtime?.events||[])].reverse();return `<div class="body">${heading("Telemetry","Event stream",`${list.length} recent`)}${list.length?list.map(e=>`<div class="event"><span class="mono">T+${e.tick}</span><span class="type">${esc(e.event_type)}</span><span>${esc(e.message)}</span></div>`).join(""):`<div class="empty">No events recorded. Step the simulation to begin.</div>`}</div>`}
async function command(name){if(name==="refresh")return refresh();if(name==="load-scenario")return loadBundledScenario();if(name==="reset"){stop();const controlledAgent=app.agent;await post("/scenario/reset");app.casualty=null;app.cell=null;await refresh();if(controlledAgent&&app.runtime.agents[controlledAgent])app.agent=controlledAgent;const agent=app.runtime.agents[app.agent];if(agent)app.z=agent.z;app.keyboardStatus="WASD moves · C cycles agents · Space acts ahead";toast("Scenario reset to its initial state");return renderAll()}if(name==="step"){await post("/step",{ticks:1});return refresh()}if(name==="run"){if(app.running)return stop();app.running=true;renderAll();app.timer=setInterval(async()=>{try{await post("/step",{ticks:1});await refresh();if(app.runtime.ended)stop()}catch(e){stop();report(e)}},450);return}if(name==="z-down")app.z=Math.max(0,app.z-1);if(name==="z-up")app.z=Math.min((app.runtime?.z_levels||1)-1,app.z+1);if(name==="editor-z-down")app.editorZ=Math.max(0,app.editorZ-1);if(name==="editor-z-up")app.editorZ=Math.min(app.editor.grid.Z-1,app.editorZ+1);if(name==="new"){app.activeZoneId=null;app.editor=normalize(blank());createZone();app.editorCell=null;sync()}if(name==="import"){app.editor=normalize(await api("/scenario/current"));sync();toast("Imported active simulation")}if(name==="format"){parse();sync()}if(name==="validate"){parse();const r=await post("/scenario/validate",{scenario:app.editor});toast(`Valid · ${r.agents} agents · ${r.casualties} casualties · ${r.zones} zones`)}if(name==="apply"){parse();await post("/scenario/load",{scenario:app.editor});app.scenarioPath="";await refresh();setWorkspaceMode("simulation");toast("Authored scenario loaded in Simulation mode")}if(name==="download")download();renderAll()}
function stop(){if(app.timer)clearInterval(app.timer);app.timer=null;app.running=false;renderAll()}
async function loadBundledScenario(){if(!app.scenarioPath)throw new Error("Choose a bundled scenario first");stop();await post("/scenario/load-from-path",{filepath:app.scenarioPath});app.agent=null;app.casualty=null;app.cell=null;app.z=0;await refresh();app.editor=normalize(await api("/scenario/current"));sync();const scenario=app.scenarios.find(v=>v.path===app.scenarioPath);toast(`${scenario?.name||"Scenario"} loaded`)}
async function issue(type){if(app.runtime?.ended){app.keyboardStatus="Mission ended · reload the scenario before issuing more actions";renderAll();return}if(!app.agent)throw new Error("Select an agent first");const casualtyActions=["TRIAGE","RETRIEVE_BODY","LOAD_CASUALTY"],coordActions=["CLEAR_DEBRIS","BREACH_ENTRYWAY"];if(casualtyActions.includes(type)&&!app.casualty)throw new Error("Select a target casualty");if(coordActions.includes(type)&&!app.cell)throw new Error("Select a target map cell");const action={action_id:`ui-${Date.now()}`,actor_id:app.agent,action_type:type};if(casualtyActions.includes(type))action.target_casualty_id=app.casualty;if(coordActions.includes(type))action.target_coord=app.cell;await post("/actions",{actions:[action]});await post("/step",{ticks:1});await refresh()}
function flashKeyboardActions(types){app.keyboardHighlight=types;clearTimeout(app.keyboardHighlightTimer);app.keyboardHighlightTimer=setTimeout(()=>{app.keyboardHighlight=[];renderAll()},650)}
async function executeKeyboardActions(actions,highlights,status){if(app.runtime?.ended){app.keyboardStatus="Mission ended · reload the scenario before issuing more actions";renderAll();return}if(!app.agent){app.keyboardStatus="Select an agent before using keyboard controls";renderAll();return}if(app.keyboardBusy)return;app.keyboardBusy=true;app.keyboardStatus=status;flashKeyboardActions(highlights);renderAll();try{await post("/actions",{actions:actions.map((action,index)=>({action_id:`keyboard-${Date.now()}-${index}`,actor_id:app.agent,...action}))});await post("/step",{ticks:1});await refresh();const agent=app.runtime?.agents?.[app.agent];if(agent){app.z=agent.z;renderAll()}}finally{app.keyboardBusy=false}}
function cycleControlledAgent(){const agents=Object.values(app.runtime?.agents||{});if(!agents.length){app.keyboardStatus="C · no agents available";return renderAll()}const index=agents.findIndex(agent=>agent.id===app.agent),agent=agents[(index+1+agents.length)%agents.length];app.agent=agent.id;app.z=agent.z;app.cell={x:agent.x,y:agent.y,z:agent.z};app.keyboardStatus=`C · controlling ${agent.id} (${agent.agent_class})`;renderAll()}
async function moveSelectedAgent(direction,key){const agent=app.runtime?.agents?.[app.agent];if(!agent){app.keyboardStatus=`${key} · select an agent to move`;renderAll();return}const directions=["NORTH","EAST","SOUTH","WEST"],current=directions.indexOf(agent.orientation),target=directions.indexOf(direction);if(current<0)throw new Error(`Unknown agent orientation: ${agent.orientation}`);const turns=(target-current+directions.length)%directions.length,actions=[],highlights=["MOVE_FORWARD"];if(turns===1){actions.push({action_type:"TURN_RIGHT"});highlights.unshift("TURN_RIGHT")}else if(turns===2){actions.push({action_type:"TURN_RIGHT"},{action_type:"TURN_RIGHT"});highlights.unshift("TURN_RIGHT")}else if(turns===3){actions.push({action_type:"TURN_LEFT"});highlights.unshift("TURN_LEFT")}actions.push({action_type:"MOVE_FORWARD"});await executeKeyboardActions(actions,highlights,`${key} · move ${direction.toLowerCase()}`)}
async function performActionInFront(){const state=app.runtime,agent=state?.agents?.[app.agent];if(!state||!agent){app.keyboardStatus="Space · select an agent first";renderAll();return}const delta={NORTH:{x:0,y:-1},EAST:{x:1,y:0},SOUTH:{x:0,y:1},WEST:{x:-1,y:0}}[agent.orientation];if(!delta)throw new Error(`Unknown agent orientation: ${agent.orientation}`);const target={x:agent.x+delta.x,y:agent.y+delta.y,z:agent.z};if(!runtimeCoordVisible(target)){app.keyboardStatus="Space · target is outside the controlled agent sensor view";return renderAll()}const atTarget=item=>item.x===target.x&&item.y===target.y&&item.z===target.z,casualty=Object.values(state.casualties).find(item=>atTarget(item)&&item.transport_status==="ON_GROUND"),gridCell=state.grid_cells.find(atTarget),building=Object.values(state.buildings).flatMap(item=>item.cells).find(item=>atTarget(item)&&!item.collapsed),hospital=state.zones.some(zone=>zone.zone_type==="FIELD_HOSPITAL"&&zone.cells.some(atTarget));app.cell=target;if(casualty){app.casualty=casualty.id;if(casualty.is_covered||gridCell?.status==="PASSABLE")return executeKeyboardActions([{action_type:"CLEAR_DEBRIS",target_coord:target}],["CLEAR_DEBRIS"],`Space · clear debris covering ${casualty.id}`);if(casualty.living_state==="DECEASED")return executeKeyboardActions([{action_type:"RETRIEVE_BODY",target_casualty_id:casualty.id}],["RETRIEVE_BODY"],`Space · retrieve ${casualty.id}`);if(casualty.triage_state==="UNKNOWN")return executeKeyboardActions([{action_type:"TRIAGE",target_casualty_id:casualty.id}],["TRIAGE"],`Space · triage ${casualty.id}`);return executeKeyboardActions([{action_type:"LOAD_CASUALTY",target_casualty_id:casualty.id}],["LOAD_CASUALTY"],`Space · load ${casualty.id}`)}if(hospital&&agent.payload_casualty_id)return executeKeyboardActions([{action_type:"TRANSFER_CASUALTY"}],["TRANSFER_CASUALTY"],"Space · transfer casualty to field hospital");if(building)return executeKeyboardActions([{action_type:"BREACH_ENTRYWAY",target_coord:target}],["BREACH_ENTRYWAY"],"Space · breach building entry");if(gridCell?.status==="PASSABLE")return executeKeyboardActions([{action_type:"CLEAR_DEBRIS",target_coord:target}],["CLEAR_DEBRIS"],"Space · clear debris");app.keyboardStatus="Space · nothing actionable directly ahead";renderAll()}
function normalize(s){if(!s?.grid||!Number.isInteger(+s.grid.N)||!Number.isInteger(+s.grid.Z))throw new Error("Scenario requires integer grid.N and grid.Z");s.grid.cells??=[];s.grid.smoke??=[];for(const k of ["agents","casualties","buildings","zones","scheduled_events"])s[k]??=[];s.metadata??={};s.metadata.scenario_id??="editor-scenario";s.metadata.name??="Editor Scenario";s.objectives??={};s.objectives.primary_goals??=["stabilize casualties"];s.evaluation??={};s.evaluation.expected_difficulty??="medium";s.perception??={};s.perception.regime??="FULL";s.perception.range=Math.max(1,Math.round(+s.perception.range||4));s.perception.cone_angle_degrees=clamp(+s.perception.cone_angle_degrees||90,1,360);if(!s.zones.some(v=>v.id===app.activeZoneId))app.activeZoneId=s.zones[0]?.id||null;return s}
function parse(){const text=document.querySelector("[data-json]");if(text)app.editorText=text.value;app.editor=normalize(JSON.parse(app.editorText));app.editorText=JSON.stringify(app.editor,null,2)}
function sync(){app.editorText=JSON.stringify(app.editor,null,2);app.editorZ=Math.min(app.editorZ,app.editor.grid.Z-1);renderAll()}
function activeZone(){return app.editor.zones.find(v=>v.id===app.activeZoneId)||null}
function defaultZoneLabels(type){return type==="FIELD_HOSPITAL"?["medical-dropoff","field-hospital"]:["editor","extraction"]}
function createZone(type="EXTRACTION"){const prefix=type==="FIELD_HOSPITAL"?"field-hospital":"extraction";let i=1;while(app.editor.zones.some(v=>v.id===`${prefix}-${i}`))i++;const zone={id:`${prefix}-${i}`,zone_type:type,cells:[],labels:defaultZoneLabels(type)};app.editor.zones.push(zone);app.activeZoneId=zone.id;return zone}
function clearEditorCell(coord){const s=app.editor;s.grid.cells=s.grid.cells.filter(v=>!same(v.coord,coord));s.grid.smoke=s.grid.smoke.filter(v=>!same(v.coord,coord));s.agents=s.agents.filter(v=>!same(v.coord,coord));s.casualties=s.casualties.filter(v=>!same(v.coord,coord));s.buildings=s.buildings.map(b=>({...b,cells:b.cells.filter(v=>!same(v.coord,coord))})).filter(b=>b.cells.length);s.zones.forEach(v=>v.cells=v.cells.filter(c=>!same(c,coord)))}
function paint(x,y,z){const s=app.editor,coord={x,y,z},ground={x,y,z:0};app.editorCell=coord;if(app.tool==="select")return renderAll();if(app.tool==="clear"){clearEditorCell(coord);app.editorStatus=`Cleared cell (${x}, ${y}, ${z})`}else if(app.tool==="wall"){upsert(s.grid.cells,coord,{coord,status:"IMPASSABLE"});app.editorStatus=`Placed wall at (${x}, ${y}, ${z})`}else if(app.tool==="debris"){upsert(s.grid.cells,ground,{coord:ground,status:"PASSABLE"});const casualty=s.casualties.find(v=>same(v.coord,ground));if(casualty)casualty.is_covered=true;app.editorStatus=`Placed debris at (${x}, ${y}, 0)`}else if(app.tool==="smoke"){upsert(s.grid.smoke,coord,{coord,density:.7});app.editorStatus=`Placed smoke at (${x}, ${y}, ${z})`}else if(app.tool==="agent"){if(s.agents.some(v=>same(v.coord,coord)))app.editorStatus=`Agent position (${x}, ${y}, ${z}) is already occupied`;else{s.agents.push({id:next(s.agents,"A"),coord,orientation:"NORTH",agent_class:z?"UAV":"UGV",busy_ticks_remaining:0,damage_status:null,payload_casualty_id:null});app.editorStatus=`Placed agent at (${x}, ${y}, ${z})`}}else if(app.tool==="casualty"&&!s.casualties.some(v=>same(v.coord,ground))){s.casualties.push({id:next(s.casualties,"C"),coord:ground,health:50,decay_rate:1,is_covered:s.grid.cells.some(v=>same(v.coord,ground)&&v.status==="PASSABLE"),triage_state:"UNKNOWN",transport_status:"ON_GROUND",living_state:"ALIVE"});app.editorStatus=`Placed casualty at (${x}, ${y}, 0)`}else if(app.tool==="building"){let building=s.buildings.find(b=>b.cells.some(v=>v.coord.x===x&&v.coord.y===y));if(!building){building={id:next(s.buildings,"B"),cells:[]};s.buildings.push(building)}if(!building.cells.some(v=>same(v.coord,coord)))building.cells.push({coord,integrity:.8,collapsed:false});upsert(s.grid.cells,coord,{coord,status:"IMPASSABLE"});app.editorStatus=`Placed building level at (${x}, ${y}, ${z})`}else if(app.tool==="zone"){const zone=activeZone()||createZone();const index=zone.cells.findIndex(v=>same(v,ground));if(index>=0)zone.cells.splice(index,1);else zone.cells.push(ground);app.editorStatus=`${index>=0?"Removed from":"Added to"} zone ${zone.id}`}sync()}
async function editorAction(name){const s=app.editor,v=editorSelection();if(name==="new-scenario"){app.activeZoneId=null;app.editor=normalize(blank());createZone();app.editorCell=null;app.editorZ=0;app.editorStatus="Created a new blank scenario";return sync()}if(name==="regenerate"){app.editor=normalize(await post("/scenario/generate",{grid_size:s.grid.N,z_depth:s.grid.Z,agent_count:Math.max(2,s.agents.length),seed:42}));app.activeZoneId=app.editor.zones[0]?.id||null;app.editorCell=null;app.editorZ=0;app.editorStatus="Regenerated deterministic scenario with seed 42";return sync()}if(name==="validate"){const result=await post("/scenario/validate",{scenario:s});app.editorStatus=`Valid scenario · ${result.agents} agents · ${result.casualties} casualties · ${result.zones} zones`;renderAll();return}if(name==="download"){app.editorText=JSON.stringify(s,null,2);saveScenarioFile();app.editorStatus="Scenario JSON downloaded";renderAll();return}if(name==="new-zone"){const zone=createZone(activeZone()?.zone_type||"EXTRACTION");app.editorStatus=`Created zone ${zone.id}`;return sync()}if(name==="add-event"){if(!v){app.editorStatus="Select a cell before adding an event";return renderAll()}let i=1;while(s.scheduled_events.some(e=>e.event_id===`evt-${i}`))i++;s.scheduled_events.push({event_id:`evt-${i}`,tick:10+s.scheduled_events.length*5,event_type:"SMOKE_INCREASE",payload:{coord:{...v.coord},density:.8}});app.editorStatus=`Added smoke event evt-${i} at T+${10+(s.scheduled_events.length-1)*5}`;return sync()}if(name==="remove-event"){const removed=s.scheduled_events.pop();app.editorStatus=removed?`Removed scheduled event ${removed.event_id}`:"No scheduled events to remove";return sync()}if(!v){app.editorStatus="Select a cell first";return renderAll()}if(name==="health-down"&&v.casualty)v.casualty.health=clamp(+v.casualty.health-10,0,100);else if(name==="health-up"&&v.casualty)v.casualty.health=clamp(+v.casualty.health+10,0,100);else if(name==="decay-down"&&v.casualty)v.casualty.decay_rate=Math.max(0,+v.casualty.decay_rate-.5);else if(name==="decay-up"&&v.casualty)v.casualty.decay_rate=Math.max(0,+v.casualty.decay_rate+.5);else if(name==="integrity-down"&&v.buildingCell)v.buildingCell.integrity=clamp(+v.buildingCell.integrity-.1,0,1);else if(name==="integrity-up"&&v.buildingCell)v.buildingCell.integrity=clamp(+v.buildingCell.integrity+.1,0,1);else if(name==="remove-agent"&&v.agent)s.agents=s.agents.filter(a=>a!==v.agent);else if(name==="remove-casualty"&&v.casualty)s.casualties=s.casualties.filter(c=>c!==v.casualty);else if(name==="remove-building"&&v.building){v.building.cells=v.building.cells.filter(c=>c!==v.buildingCell);s.buildings=s.buildings.filter(b=>b.cells.length);s.grid.cells=s.grid.cells.filter(c=>!same(c.coord,v.ground))}else if(name==="clear-selected")clearEditorCell(v.coord);app.editorStatus=`Updated selected cell (${v.x}, ${v.y}, ${v.z})`;sync()}
function updateEditorField(name,target){const s=app.editor,v=editorSelection(),value=target.value;if(name==="active-zone"){app.activeZoneId=value||null;app.editorStatus=app.activeZoneId?`Active zone: ${app.activeZoneId}`:"No active zone";return renderAll()}if(name==="scenario-name")s.metadata.name=value;else if(name==="scenario-id")s.metadata.scenario_id=value;else if(name==="difficulty")s.evaluation.expected_difficulty=value;else if(name==="sensor-regime")s.perception.regime=value;else if(name==="sensor-range")s.perception.range=Math.max(1,Math.round(+value||1));else if(name==="sensor-angle")s.perception.cone_angle_degrees=clamp(+value||90,1,360);else if(name==="constraint-enabled"){if(target.checked)s.objectives.temporal_constraint={type:"rescue_count",target_count:1,deadline_cycles:20};else delete s.objectives.temporal_constraint}else if(name==="constraint-target"&&s.objectives.temporal_constraint)s.objectives.temporal_constraint.target_count=clamp(Math.round(+value||1),1,Math.max(1,s.casualties.length));else if(name==="constraint-deadline"&&s.objectives.temporal_constraint)s.objectives.temporal_constraint.deadline_cycles=Math.max(1,Math.round(+value||1));else if(name==="zone-type"){const zone=activeZone();if(zone){zone.zone_type=value;zone.labels=defaultZoneLabels(value)}}else if(v&&name==="cell-status"){if(value==="UNOCCUPIED")s.grid.cells=s.grid.cells.filter(c=>!same(c.coord,v.coord));else upsert(s.grid.cells,v.coord,{coord:{...v.coord},status:value})}else if(v&&name==="smoke-density"){const density=clamp(+value||0,0,1);if(density===0)s.grid.smoke=s.grid.smoke.filter(entry=>!same(entry.coord,v.coord));else upsert(s.grid.smoke,v.coord,{coord:{...v.coord},density})}else if(v?.agent&&name==="agent-orientation")v.agent.orientation=value;else if(v?.agent&&name==="agent-class"){const targetZ=value==="UGV"?0:Math.min(s.grid.Z-1,Math.max(1,v.agent.coord.z)),targetCoord={...v.agent.coord,z:targetZ};if(s.agents.some(agent=>agent!==v.agent&&same(agent.coord,targetCoord)))throw new Error(`Agent position (${targetCoord.x}, ${targetCoord.y}, ${targetCoord.z}) is already occupied`);v.agent.agent_class=value;v.agent.coord=targetCoord;app.editorZ=targetZ;app.editorCell={...targetCoord}}else if(v?.casualty&&name==="casualty-health")v.casualty.health=clamp(+value||0,0,100);else if(v?.casualty&&name==="casualty-decay")v.casualty.decay_rate=Math.max(0,+value||0);else if(v?.casualty&&name==="casualty-covered")v.casualty.is_covered=target.checked;else if(v?.buildingCell&&name==="building-integrity")v.buildingCell.integrity=clamp(+value||0,0,1);else if(v?.buildingCell&&name==="building-collapsed"){v.buildingCell.collapsed=target.checked;upsert(s.grid.cells,v.ground,{coord:{...v.ground},status:target.checked?"PASSABLE":"IMPASSABLE"})}app.editorStatus="Scenario properties updated";sync()}
const clamp=(value,min,max)=>Math.min(max,Math.max(min,value));
function upsert(array,coord,value){const i=array.findIndex(v=>same(v.coord,coord));i<0?array.push(value):array[i]=value}const same=(a,b)=>a?.x===b?.x&&a?.y===b?.y&&a?.z===b?.z;function next(items,prefix){let n=items.length+1;while(items.some(v=>v.id===prefix+n))n++;return prefix+n}
function sensorLabel(regime){return ({FULL:"Full observability",FOV_CONE:"FOV cone",MINIGRID_3:"MiniGrid 3-wide"})[regime]||regime}
function coordKey(value){return `${value.x},${value.y},${value.z}`}
function runtimeVisibility(){const perception=app.runtime?.perception;if(!perception||perception.regime==="FULL")return null;return new Set((perception.visible_cells_by_agent?.[app.agent]||[]).map(coordKey))}
function runtimeCoordVisible(value){const visible=runtimeVisibility();return !visible||Boolean(value&&visible.has(coordKey(value)))}
function saveScenarioFile(){const blob=new Blob([app.editorText],{type:"application/json"}),a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=`${app.editor.metadata.scenario_id||"scenario"}.json`;a.click();URL.revokeObjectURL(a.href)}
function download(){parse();saveScenarioFile()}
function zoneMap(zones,z){const map=new Map;for(const zone of zones||[])for(const c of zone.cells||[])if(c.z===z){const key=`${c.x},${c.y}`;map.set(key,[...(map.get(key)||[]),zone])}return map}const arrow=v=>({NORTH:"▲",EAST:"▶",SOUTH:"▼",WEST:"◀"})[v]||"◆";const esc=value=>String(value).replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"})[c]);

document.addEventListener("click",async event=>{const target=event.target.closest("button");if(!target)return;try{if(target.dataset.workspaceMode){setWorkspaceMode(target.dataset.workspaceMode);return}if(target.dataset.command)await command(target.dataset.command);if(target.dataset.action)await issue(target.dataset.action);if(target.dataset.editorAction)await editorAction(target.dataset.editorAction);if(target.dataset.runtimeCell){const [x,y,z]=target.dataset.runtimeCell.split(",").map(Number);app.cell={x,y,z};const a=Object.values(app.runtime.agents).find(v=>v.x===x&&v.y===y&&v.z===z),c=Object.values(app.runtime.casualties).find(v=>v.x===x&&v.y===y&&v.z===z);if(a)app.agent=a.id;if(c)app.casualty=c.id;renderAll()}if(target.dataset.tool){app.tool=target.dataset.tool;if(["debris","casualty","zone"].includes(app.tool))app.editorZ=0;app.editorStatus=`${target.textContent.trim()} tool selected`;renderAll()}if(target.dataset.editorCell){const [x,y,z]=target.dataset.editorCell.split(",").map(Number);paint(x,y,z)}}catch(e){report(e)}});
document.addEventListener("change",async event=>{const t=event.target;try{if(t.dataset.control==="agent")app.agent=t.value||null;if(t.dataset.control==="casualty")app.casualty=t.value||null;if(t.dataset.control==="scenario")app.scenarioPath=t.value;if(t.dataset.editorField)updateEditorField(t.dataset.editorField,t);if(t.matches("[data-file]")&&t.files[0]){app.editorText=await t.files[0].text();parse();app.editorStatus=`Opened ${t.files[0].name}`;sync()}renderAll()}catch(e){report(e)}});
document.addEventListener("input",event=>{if(event.target.matches("[data-json]"))app.editorText=event.target.value});
document.addEventListener("keydown",async event=>{if(app.mode!=="simulation"||event.repeat||event.ctrlKey||event.metaKey||event.altKey)return;const target=event.target;if(target instanceof Element&&target.closest("input,textarea,select,[contenteditable=true],[role=textbox]"))return;const key=String(event.key||"").toLowerCase(),code=event.code||({w:"KeyW",a:"KeyA",s:"KeyS",d:"KeyD",c:"KeyC"," ":"Space",spacebar:"Space"})[key],directions={KeyW:"NORTH",KeyA:"WEST",KeyS:"SOUTH",KeyD:"EAST"};if(!directions[code]&&code!=="Space"&&code!=="KeyC")return;event.preventDefault();event.stopPropagation();try{if(code==="KeyC")cycleControlledAgent();else if(code==="Space")await performActionInFront();else await moveSelectedAgent(directions[code],code.slice(-1))}catch(error){app.keyboardStatus=`Keyboard · ${error.message||String(error)}`;renderAll();report(error)}},true);
document.querySelector("#add-panel").addEventListener("change",event=>{const kind=event.target.value;if(kind&&panelKinds[app.mode].includes(kind))layout.addComponent(kind,{},names[kind]);event.target.value=""});
document.querySelector("#save-layout").addEventListener("click",()=>{if(!saveCurrentWorkspace()){restoreDefaultWorkspace();toast("Invalid workspace replaced with the default layout",true);return}toast(`${workspaceLabel()} layout saved`)});
document.querySelector("#reset-layout").addEventListener("click",()=>{restoreDefaultWorkspace();toast(`Default ${workspaceLabel().toLowerCase()} layout restored`)});
let toastTimer;function toast(text,error=false){const el=document.querySelector("#toast");el.textContent=text;el.className=`show ${error?"error":""}`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.className="",3200)}function report(error){console.error(error);toast(error.message||String(error),true)}
function workspaceLabel(){return app.mode==="editing"?"Scenario editor":"Simulation"}
function cloneDefaultLayout(mode=app.mode){return JSON.parse(JSON.stringify(defaultLayouts[mode]))}
function resizeLayout(){layout.setSize(layoutHost.clientWidth,layoutHost.clientHeight)}
function visiblePanelKinds(){return [...layoutHost.querySelectorAll("[data-panel]")].map(el=>el.dataset.panel)}
function hasValidWorkspace(mode=app.mode){const visible=visiblePanelKinds(),allowed=panelKinds[mode];return Boolean(layout.rootItem)&&visible.length>0&&visible.every(kind=>allowed.includes(kind))}
function updateWorkspaceChrome(){document.body.dataset.workspace=app.mode;for(const button of document.querySelectorAll("[data-workspace-mode]")){const active=button.dataset.workspaceMode===app.mode;button.classList.toggle("active",active);button.setAttribute("aria-pressed",String(active))}const picker=document.querySelector("#add-panel");if(picker.dataset.mode!==app.mode){picker.replaceChildren(new Option("+ Add panel",""),...panelKinds[app.mode].map(kind=>new Option(names[kind],kind)));picker.dataset.mode=app.mode}}
function saveCurrentWorkspace(){if(!hasValidWorkspace())return false;localStorage.setItem(layoutKeys[app.mode],JSON.stringify(layout.saveLayout()));return true}
function restoreDefaultWorkspace(){localStorage.removeItem(layoutKeys[app.mode]);layout.loadLayout(cloneDefaultLayout());resizeLayout();updateWorkspaceChrome()}
function loadWorkspace(mode){let candidate=cloneDefaultLayout(mode),restoring=false;try{const saved=localStorage.getItem(layoutKeys[mode]);if(saved){candidate=LayoutConfig.fromResolved(JSON.parse(saved));restoring=true}}catch(error){console.warn(`Discarding unreadable ${mode} workspace`,error);localStorage.removeItem(layoutKeys[mode])}try{layout.loadLayout(candidate);resizeLayout();if(!hasValidWorkspace(mode))throw new Error(`${mode} workspace contains invalid panels`)}catch(error){if(!restoring)throw error;console.warn(`Discarding invalid saved ${mode} workspace`,error);localStorage.removeItem(layoutKeys[mode]);layout.loadLayout(cloneDefaultLayout(mode));resizeLayout()}updateWorkspaceChrome()}
function setWorkspaceMode(mode){if(!panelKinds[mode]||mode===app.mode)return;if(hasValidWorkspace())saveCurrentWorkspace();if(app.timer){clearInterval(app.timer);app.timer=null;app.running=false}app.mode=mode;localStorage.setItem(modeKey,mode);loadWorkspace(mode);renderAll()}
function initializeWorkspace(){const savedMode=localStorage.getItem(modeKey);app.mode=panelKinds[savedMode]?savedMode:"simulation";loadWorkspace(app.mode)}
async function start(){try{initializeWorkspace();app.scenarios=await api("/scenarios");await refresh();if(!Object.keys(app.runtime.agents).length){await post("/init/dev");await refresh()}app.editor=normalize(await api("/scenario/current"));sync()}catch(e){connection(false);report(e)}}
start();
